-- ResumeIQ database schema
-- PostgreSQL 17
-- Based on the approved AI Resume Analyzer & Career Recommendation System ER diagram.
--
-- Run this file while connected to the "resumeiq" database:
--   psql -d resumeiq -f database/schema.sql
--
-- Notes:
-- 1. UUID primary keys are generated by PostgreSQL's gen_random_uuid().
-- 2. ANALYSIS links one user, one resume, and one job description.
-- 3. RESUME_SKILLS and JOB_SKILLS implement the many-to-many skill relationships.
-- 4. The ER diagram does not specify detailed data types or all foreign-key
--    placements. The choices below are practical implementation decisions.

BEGIN;

-- USERS
CREATE TABLE IF NOT EXISTS users (
    user_id       UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name          VARCHAR(150) NOT NULL,
    email         VARCHAR(255) NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    role          VARCHAR(30) NOT NULL DEFAULT 'user',
    created_at    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT users_role_check CHECK (role IN ('user', 'admin'))
);

-- RESUMES
CREATE TABLE IF NOT EXISTS resumes (
    resume_id    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id      UUID NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    resume_title VARCHAR(200) NOT NULL,
    file_path    TEXT NOT NULL,
    upload_date  TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- JOB_DESCRIPTIONS
CREATE TABLE IF NOT EXISTS job_descriptions (
    job_id      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    job_title   VARCHAR(200) NOT NULL,
    company     VARCHAR(200),
    description TEXT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- SKILLS
CREATE TABLE IF NOT EXISTS skills (
    skill_id   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    skill_name VARCHAR(120) NOT NULL UNIQUE,
    category   VARCHAR(100)
);

-- ANALYSIS
-- Each analysis belongs to a user, a resume, and a target job description.
CREATE TABLE IF NOT EXISTS analysis (
    analysis_id   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       UUID NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    resume_id     UUID NOT NULL REFERENCES resumes(resume_id) ON DELETE CASCADE,
    job_id        UUID NOT NULL REFERENCES job_descriptions(job_id) ON DELETE CASCADE,
    match_score   NUMERIC(5,2) NOT NULL DEFAULT 0,
    analysis_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT analysis_match_score_check CHECK (match_score >= 0 AND match_score <= 100)
);

-- RESUME_SKILLS: skills detected in a resume.
CREATE TABLE IF NOT EXISTS resume_skills (
    resume_id  UUID NOT NULL REFERENCES resumes(resume_id) ON DELETE CASCADE,
    skill_id   UUID NOT NULL REFERENCES skills(skill_id) ON DELETE CASCADE,
    proficiency VARCHAR(50),
    PRIMARY KEY (resume_id, skill_id)
);

-- JOB_SKILLS: skills required or preferred by a job description.
CREATE TABLE IF NOT EXISTS job_skills (
    job_id          UUID NOT NULL REFERENCES job_descriptions(job_id) ON DELETE CASCADE,
    skill_id        UUID NOT NULL REFERENCES skills(skill_id) ON DELETE CASCADE,
    requirement_type VARCHAR(30) NOT NULL DEFAULT 'required',
    PRIMARY KEY (job_id, skill_id),
    CONSTRAINT job_skills_requirement_type_check
        CHECK (requirement_type IN ('required', 'preferred'))
);

-- RECOMMENDATIONS
CREATE TABLE IF NOT EXISTS recommendations (
    recommendation_id   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    analysis_id         UUID NOT NULL REFERENCES analysis(analysis_id) ON DELETE CASCADE,
    recommendation_text TEXT NOT NULL,
    priority            VARCHAR(20) NOT NULL DEFAULT 'medium',
    CONSTRAINT recommendations_priority_check
        CHECK (priority IN ('low', 'medium', 'high'))
);

-- ATS_ANALYSIS
CREATE TABLE IF NOT EXISTS ats_analysis (
    ats_id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    analysis_id     UUID NOT NULL REFERENCES analysis(analysis_id) ON DELETE CASCADE,
    ats_score       NUMERIC(5,2) NOT NULL DEFAULT 0,
    keyword_score   NUMERIC(5,2) NOT NULL DEFAULT 0,
    formatting_score NUMERIC(5,2) NOT NULL DEFAULT 0,
    CONSTRAINT ats_score_check CHECK (ats_score >= 0 AND ats_score <= 100),
    CONSTRAINT ats_keyword_score_check CHECK (keyword_score >= 0 AND keyword_score <= 100),
    CONSTRAINT ats_formatting_score_check CHECK (formatting_score >= 0 AND formatting_score <= 100)
);

-- CAREER_RECOMMENDATIONS
CREATE TABLE IF NOT EXISTS career_recommendations (
    career_recommendation_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    analysis_id      UUID NOT NULL REFERENCES analysis(analysis_id) ON DELETE CASCADE,
    career_title     VARCHAR(200) NOT NULL,
    match_percentage NUMERIC(5,2) NOT NULL DEFAULT 0,
    CONSTRAINT career_match_percentage_check
        CHECK (match_percentage >= 0 AND match_percentage <= 100)
);

-- SKILL_GAPS
CREATE TABLE IF NOT EXISTS skill_gaps (
    gap_id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    analysis_id     UUID NOT NULL REFERENCES analysis(analysis_id) ON DELETE CASCADE,
    skill_id        UUID NOT NULL REFERENCES skills(skill_id) ON DELETE CASCADE,
    reason          TEXT,
    importance_level VARCHAR(20) NOT NULL DEFAULT 'medium',
    CONSTRAINT skill_gaps_importance_check
        CHECK (importance_level IN ('low', 'medium', 'high')),
    CONSTRAINT skill_gaps_analysis_skill_unique UNIQUE (analysis_id, skill_id)
);

-- Indexes for common foreign-key lookups and dashboard/history queries.
CREATE INDEX IF NOT EXISTS idx_resumes_user_id ON resumes(user_id);
CREATE INDEX IF NOT EXISTS idx_analysis_user_id ON analysis(user_id);
CREATE INDEX IF NOT EXISTS idx_analysis_resume_id ON analysis(resume_id);
CREATE INDEX IF NOT EXISTS idx_analysis_job_id ON analysis(job_id);
CREATE INDEX IF NOT EXISTS idx_analysis_date ON analysis(analysis_date DESC);
CREATE INDEX IF NOT EXISTS idx_job_descriptions_title ON job_descriptions(job_title);
CREATE INDEX IF NOT EXISTS idx_resume_skills_skill_id ON resume_skills(skill_id);
CREATE INDEX IF NOT EXISTS idx_job_skills_skill_id ON job_skills(skill_id);
CREATE INDEX IF NOT EXISTS idx_recommendations_analysis_id ON recommendations(analysis_id);
CREATE INDEX IF NOT EXISTS idx_ats_analysis_analysis_id ON ats_analysis(analysis_id);
CREATE INDEX IF NOT EXISTS idx_career_recommendations_analysis_id
    ON career_recommendations(analysis_id);
CREATE INDEX IF NOT EXISTS idx_skill_gaps_analysis_id ON skill_gaps(analysis_id);

COMMIT;

-- Verify tables after running:
--   \dt
--   \d users
--   \d analysis
